<section class="module-toolbar"><div><p class="module-intro">Ürün kataloğunuzu ve stok seviyelerinizi yönetin.</p><span class="result-count"><?= number_format($total,0,',','.') ?> ürün kaydı</span></div><?php if(kd_can('products.manage')): ?><a class="btn primary action-link" href="index.php?page=products&action=create">＋ Yeni ürün</a><?php endif; ?></section>
<section class="grid grid-3 dashboard-metrics">
<div class="panel metric-card"><span>Stok değeri</span><strong><?= number_format((float)($summary['stock_value']??0),2,',','.') ?> ₺</strong><small>Mevcut miktar × ağırlıklı alış maliyeti</small></div>
<div class="panel metric-card"><span>Kritik stok</span><strong><?= number_format((int)($summary['low_stock_count']??0),0,',','.') ?></strong><small>Minimum stok seviyesinde veya altında</small></div>
<div class="panel metric-card"><span>Stoksuz ürün</span><strong><?= number_format((int)($summary['out_of_stock_count']??0),0,',','.') ?></strong><small>Stok takibi açık, miktarı sıfır veya altında</small></div>
</section>
<section class="panel customer-list-panel">
<form class="filter-bar" method="get"><input type="hidden" name="page" value="products"><label class="filter-search"><span>⌕</span><input type="search" name="q" value="<?= kd_e($q) ?>" placeholder="Ürün adı, stok kodu veya barkod ara"></label><select name="category_id"><option value="0">Tüm kategoriler</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= $categoryId===(int)$category['id']?'selected':'' ?>><?= kd_e($category['name']) ?></option><?php endforeach; ?></select><select name="status"><option value="">Tüm durumlar</option><option value="active" <?= $status==='active'?'selected':'' ?>>Aktif</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Pasif</option></select><select name="stock_status"><option value="">Tüm stoklar</option><option value="low" <?= $stockStatus==='low'?'selected':'' ?>>Kritik stok</option><option value="out" <?= $stockStatus==='out'?'selected':'' ?>>Stoksuz</option><option value="healthy" <?= $stockStatus==='healthy'?'selected':'' ?>>Yeterli stok</option></select><button class="btn secondary" type="submit">Filtrele</button><?php if($q!==''||$categoryId>0||$status!==''||$stockStatus!==''): ?><a class="clear-filter" href="index.php?page=products">Temizle</a><?php endif; ?></form>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Ürün</th><th>Kategori</th><th>Alış fiyatı</th><th>Satış fiyatı</th><th>Stok</th><th>Durum</th><th></th></tr></thead><tbody>
<?php foreach($products as $product): $low=(int)$product['track_stock']===1&&(float)$product['stock_quantity']<=(float)$product['min_stock']; ?><tr><td><a class="customer-name" href="index.php?page=products&action=view&id=<?= (int)$product['id'] ?>"><?= kd_e($product['name']) ?></a><small class="table-sub"><?= kd_e($product['sku']?:'—') ?></small></td><td><?= kd_e($product['category_name']?:'Genel') ?></td><td><?= number_format((float)$product['purchase_price'],2,',','.') ?> ₺</td><td><strong><?= number_format((float)$product['sale_price'],2,',','.') ?> ₺</strong></td><td><span class="stock-value <?= $low?'stock-low':'' ?>"><?= number_format((float)$product['stock_quantity'],3,',','.') ?> <?= kd_e($product['unit']) ?></span><?php if($low): ?><small class="table-sub">Kritik stok</small><?php endif; ?></td><td><span class="customer-status <?= $product['status']==='active'?'is-active':'is-inactive' ?>"><?= $product['status']==='active'?'Aktif':'Pasif' ?></span></td><td class="table-actions"><a href="index.php?page=products&action=view&id=<?= (int)$product['id'] ?>" aria-label="Görüntüle">↗</a><?php if(kd_can('products.manage')): ?><a href="index.php?page=products&action=edit&id=<?= (int)$product['id'] ?>" aria-label="Düzenle">✎</a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$products): ?><tr><td colspan="7"><div class="empty-state"><strong>Henüz ürün bulunmuyor</strong><p>İlk ürün kartınızı oluşturarak başlayın.</p></div></td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1): ?><div class="pagination"><span><?= $page ?> / <?= $pages ?> sayfa</span><div><?php if($page>1): ?><a href="<?= kd_e('index.php?page=products&q='.rawurlencode($q).'&category_id='.$categoryId.'&status='.rawurlencode($status).'&stock_status='.rawurlencode($stockStatus).'&p='.($page-1)) ?>">← Önceki</a><?php endif; ?><?php if($page<$pages): ?><a href="<?= kd_e('index.php?page=products&q='.rawurlencode($q).'&category_id='.$categoryId.'&status='.rawurlencode($status).'&p='.($page+1)) ?>">Sonraki →</a><?php endif; ?></div></div><?php endif; ?>
</section>
